import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-09-07","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-09-07","date":"2021-09-07T00:00:00.000Z","updated":"2021-09-12T00:00:00.000Z","tags":["Ceph","Orchestrator","Agent","Repaving Oasis","Log Aggregation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-07.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-07.md","lastUpdated":1780460162000}'),o={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-09-07.md"};function l(s,a,n,h,g,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-本周的orchestrator周会" tabindex="-1">会议主题：本周的Orchestrator周会 <a class="header-anchor" href="#会议主题-本周的orchestrator周会" aria-label="Permalink to &quot;会议主题：本周的Orchestrator周会&quot;">​</a></h4><h4 id="参会人员-全体成员" tabindex="-1">参会人员：全体成员 <a class="header-anchor" href="#参会人员-全体成员" aria-label="Permalink to &quot;参会人员：全体成员&quot;">​</a></h4><h4 id="会议时间-2021年9月7日" tabindex="-1">会议时间：2021年9月7日 <a class="header-anchor" href="#会议时间-2021年9月7日" aria-label="Permalink to &quot;会议时间：2021年9月7日&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Agent介绍</strong> - 由Edin进行</li><li><strong>Repaving Oasis</strong> - 由Cory进行</li><li><strong>测试重启</strong></li><li><strong>日志聚合需求</strong></li></ol><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><h5 id="_1-agent介绍" tabindex="-1">1. Agent介绍 <a class="header-anchor" href="#_1-agent介绍" aria-label="Permalink to &quot;1. Agent介绍&quot;">​</a></h5><ul><li><strong>目的</strong>：提高可扩展性和性能，解决当前使用SSH通信的慢速问题。</li><li><strong>架构</strong>：使用HTTP端点和非容器化的systemd单元，通过原始套接字通信。</li><li><strong>安全性</strong>：使用HTTPS、自签名证书和密钥环确保通信安全。</li><li><strong>元数据完整性</strong>：使用计数器确保元数据的时效性。</li><li><strong>离线主机处理</strong>：通过超时机制快速检测离线主机，并重新部署Agent。</li></ul><h5 id="_2-repaving-oasis" tabindex="-1">2. Repaving Oasis <a class="header-anchor" href="#_2-repaving-oasis" aria-label="Permalink to &quot;2. Repaving Oasis&quot;">​</a></h5><ul><li><strong>目的</strong>：自动化OSD的重铺过程，例如更改最小分配大小或使用db wal。</li><li><strong>方法</strong>：使用现有的驱动组定义来重新部署OSD。</li><li><strong>命令</strong>：设想一个新的命令来启动重铺过程，例如<code>ceph osd repave</code>。</li><li><strong>测试</strong>：需要验证在混合OSD（SSD和硬盘）情况下的正确行为。</li></ul><h5 id="_3-测试重启" tabindex="-1">3. 测试重启 <a class="header-anchor" href="#_3-测试重启" aria-label="Permalink to &quot;3. 测试重启&quot;">​</a></h5><ul><li><strong>目的</strong>：避免在重启过程中出现Monmap问题。</li><li><strong>方法</strong>：使用现有的压力测试工具（如Thrasher）进行测试。</li></ul><h5 id="_4-日志聚合需求" tabindex="-1">4. 日志聚合需求 <a class="header-anchor" href="#_4-日志聚合需求" aria-label="Permalink to &quot;4. 日志聚合需求&quot;">​</a></h5><ul><li><strong>目的</strong>：聚合集群中的日志，可能用于支持案例。</li><li><strong>讨论</strong>：建议使用外部工具（如EFK堆栈）来处理日志聚合。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>Agent的架构和安全性细节已经明确，后续将进行进一步的开发和测试。</li><li>Repaving Oasis的初步方案已经提出，Cory将开始进行详细设计和开发。</li><li>重启测试将使用现有的压力测试工具进行。</li><li>日志聚合可能通过外部工具实现，而不是在管理器模块中。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Edin将继续开发和完善Agent的功能。</li><li>Cory将开始Repaving Oasis的详细设计和开发工作。</li><li>使用Thrasher进行重启测试。</li><li>考虑使用外部工具进行日志聚合，并可能提供相关文档。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢大家的参与，下次会议再见。</p><p>以上是本次会议的详细纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',22)])])}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
